#!/usr/bin/env python3
"""
Worker Converter (Encoder / Obfuscator & Decoder / Deobfuscator)
Works on Windows, Linux, and macOS.
Zero external npm dependencies required!
"""

import sys
import os
import re
import json
import base64
import gzip
import tempfile
import subprocess
import argparse

XOR_KEY = 0x4F

EMBEDDED_ENGINE_B64_GZIP = ""

def decode_table_entry(b64_str, key):
    raw = base64.b64decode(b64_str)
    out = bytearray(raw[i] ^ (key ^ (i % 11)) for i in range(len(raw)))
    return out.decode('utf-8')

def is_valid_js_identifier(s):
    if not s:
        return False
    reserved = {
        'break', 'case', 'catch', 'class', 'const', 'continue', 'debugger', 'default',
        'delete', 'do', 'else', 'export', 'extends', 'finally', 'for', 'function',
        'if', 'import', 'in', 'instanceof', 'new', 'return', 'super', 'switch',
        'this', 'throw', 'try', 'typeof', 'var', 'void', 'while', 'with', 'yield',
        'let', 'static', 'enum', 'await', 'implements', 'interface', 'package',
        'private', 'protected', 'public', 'null', 'true', 'false', 'NaN', 'undefined'
    }
    if s in reserved:
        return False
    return bool(re.match(r'^[a-zA-Z_$][a-zA-Z0-9_$]*$', s))

def deobfuscate_worker(code):
    """
    Decodes an obfuscated worker.js back into a normal readable JavaScript file (Pure Python).
    """
    key_match = re.search(r'const _0x_key\s*=\s*(\d+);', code)
    tbl_match = re.search(r'const _0x_tbl\s*=\s*(\[.*?\]);', code, re.DOTALL)

    if not key_match or not tbl_match:
        print("[!] No encoded string table (_0x_key / _0x_tbl) found in input.")
        return code

    key = int(key_match.group(1))
    tbl = json.loads(tbl_match.group(1))
    
    # Pre-decode all strings in table
    decoded_strings = [decode_table_entry(item, key) for item in tbl]

    # Remove ts-nocheck and decoder block from source
    clean_code = re.sub(r'^//\s*@ts-nocheck\s*\n', '', code)
    decoder_pattern = r'const _0x_key\s*=\s*\d+;\s*const _0x_tbl\s*=\s*\[.*?\];\s*const _0x_cache\s*=\s*new Map\(\);\s*function func_dec\(idx\)\s*\{.*?\n\}'
    clean_code = re.sub(decoder_pattern, '', clean_code, flags=re.DOTALL)

    # Replace optional chaining property access: ?.[func_dec(123)] -> ?.prop or ?.[...]
    def replace_opt_member(match):
        idx = int(match.group(1))
        val = decoded_strings[idx]
        if is_valid_js_identifier(val):
            return f'?.{val}'
        return f'?.[{json.dumps(val)}]'

    clean_code = re.sub(r'\?\.\[func_dec\((\d+)\)\]', replace_opt_member, clean_code)

    # Replace object computed property / member access: [func_dec(123)]
    def replace_bracket_member(match):
        prefix = match.group(1)
        idx = int(match.group(2))
        val = decoded_strings[idx]
        if is_valid_js_identifier(val):
            return f'{prefix}.{val}'
        return f'{prefix}[{json.dumps(val)}]'

    clean_code = re.sub(r'([\w\$\)\]])\[func_dec\((\d+)\)\]', replace_bracket_member, clean_code)

    # Replace object literal keys: [func_dec(123)]:
    def replace_obj_key(match):
        idx = int(match.group(1))
        val = decoded_strings[idx]
        if is_valid_js_identifier(val):
            return f'{val}:'
        return f'{json.dumps(val)}:'

    clean_code = re.sub(r'\[func_dec\((\d+)\)\]\s*:', replace_obj_key, clean_code)

    # Replace all remaining func_dec(123) with json.dumps(val)
    def replace_func_dec(match):
        idx = int(match.group(1))
        val = decoded_strings[idx]
        return json.dumps(val)

    clean_code = re.sub(r'func_dec\((\d+)\)', replace_func_dec, clean_code)

    return clean_code.strip()

def obfuscate_worker(input_path, output_path):
    """
    Obfuscates normal worker.js using the self-contained standalone engine.
    Requires only Node.js runtime (no npm packages required).
    """
    abs_input = os.path.abspath(input_path)
    abs_output = os.path.abspath(output_path)

    if not os.path.exists(abs_input):
        print(f"[!] Error: Input file '{input_path}' not found.")
        sys.exit(1)

    # Check if a standalone engine file exists nearby or extract from embedded data
    script_dir = os.path.dirname(os.path.abspath(__file__))
    standalone_engine_path = os.path.join(script_dir, "worker_obfuscator_standalone.cjs")

    temp_engine_created = False
    if not os.path.exists(standalone_engine_path):
        temp_fd, standalone_engine_path = tempfile.mkstemp(suffix=".cjs", prefix="worker_engine_")
        with os.fdopen(temp_fd, "wb") as f:
            f.write(gzip.decompress(base64.b64decode(EMBEDDED_ENGINE_B64_GZIP)))
        temp_engine_created = True

    try:
        proc = subprocess.run(
            ["node", standalone_engine_path, abs_input, abs_output],
            capture_output=True,
            text=True
        )
        if proc.returncode != 0:
            print("[!] Error during encoding:\n", proc.stderr)
            sys.exit(1)
        else:
            print(proc.stdout.strip())
            print(f"[+] Successfully encoded '{input_path}' -> '{output_path}'")
    finally:
        if temp_engine_created and os.path.exists(standalone_engine_path):
            try:
                os.remove(standalone_engine_path)
            except Exception:
                pass

def main():
    parser = argparse.ArgumentParser(description="Worker.js Standalone Converter (Encoder & Decoder)")
    subparsers = parser.add_subparsers(dest="command", required=True)

    # Encode command
    encode_parser = subparsers.add_parser("encode", help="Turn normal worker.js into coded/obfuscated worker.js")
    encode_parser.add_argument("-i", "--input", default="worker.js", help="Path to input normal worker.js")
    encode_parser.add_argument("-o", "--output", default="worker.encoded.js", help="Path to output encoded worker.js")

    # Decode command
    decode_parser = subparsers.add_parser("decode", help="Turn encoded worker.js back to normal readable worker.js")
    decode_parser.add_argument("-i", "--input", default="worker.js", help="Path to input encoded worker.js")
    decode_parser.add_argument("-o", "--output", default="worker.decoded.js", help="Path to output normal worker.js")

    args = parser.parse_args()

    if args.command == "encode":
        print(f"[*] Encoding {args.input} -> {args.output}...")
        obfuscate_worker(args.input, args.output)
    elif args.command == "decode":
        print(f"[*] Decoding {args.input} -> {args.output}...")
        with open(args.input, 'r', encoding='utf-8') as f:
            code = f.read()
        decoded_code = deobfuscate_worker(code)
        with open(args.output, 'w', encoding='utf-8') as f:
            f.write(decoded_code)
        print(f"[+] Successfully decoded to {args.output}")

if __name__ == "__main__":
    main()
